@Transactional(rollbackFor = Exception.class)
public Long create(@Valid MailJobBo bo) {
    // @Valid 已兜住空值和邮箱格式，这里只判业务规则
    if (jobDao.existsByJobName(bo.getJobName())) {
        throw new BizException("任务名已存在: " + bo.getJobName());
    }
    MailReportJob job = new MailReportJob();
    BeanUtils.copyProperties(bo, job);
    job.setEnabled(1);                 // 新建默认启用
    job.setBusinessDateOffsetDays(
            bo.getBusinessDateOffsetDays() == null ? 1 : bo.getBusinessDateOffsetDays());
    jobDao.insert(job);
    // 收件人按主键批量插，和任务在同一个事务里
    insertRecipients(job.getId(), bo.getRecipients());
    return job.getId();
}

private LocalDate resolveBusinessDate(MailReportJob job) {
    int offset = job.getBusinessDateOffsetDays() == null ? 1 : job.getBusinessDateOffsetDays();
    // 只在入口算一次，后续所有地方都用这个值，不再各自取 now
    return LocalDate.now(ZoneId.of("Asia/Shanghai")).minusDays(offset);
}

